import { IGameServerResponse } from '@game-studio/server-comms';

// adds $endGameResponse data to the window for our Automated testing solution
declare global {
    interface Window {
        $endGameResponse: IValidServerResponse;
    }
}

export interface IValidator<TResponse extends IGameServerResponse> {
    isValid(message: TResponse): boolean;
    getError(message: TResponse): string;
}

export interface IValidServerResponse extends IGameServerResponse {
    GameMessage: { GameId: number };
}